CREATE DATABASE IF NOT EXISTS attendance_snap CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE attendance_snap;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('student','teacher') NOT NULL,avatar ENUM('male','female','neutral') NOT NULL DEFAULT 'neutral',class_name VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,attendance_date DATE NOT NULL,attendance_time TIME NOT NULL,photo_filename VARCHAR(255) NOT NULL,latitude DECIMAL(10,7) NOT NULL,longitude DECIMAL(10,7) NOT NULL,gps_accuracy_m DECIMAL(8,2) NOT NULL,distance_m DECIMAL(10,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE KEY one_per_day(user_id,attendance_date),INDEX idx_day(attendance_date));
